class MedianFinder {
    private PriorityQueue<Integer> lo, hi;

    public MedianFinder() {
        lo = new PriorityQueue<>(Collections.reverseOrder());   // 大顶堆，较小的一半
        hi = new PriorityQueue<>();                     // 小顶堆，较大的一半
    }

    public void addNum(int num) {
        lo.offer(num);
        hi.offer(lo.poll());                            // lo 的最大值挪到 hi
        if (hi.size() > lo.size()) {                    // 保持 lo 不比 hi 少
            lo.offer(hi.poll());
        }
    }

    public double findMedian() {
        if (lo.size() > hi.size()) {
            return lo.peek();
        }
        return (lo.peek() + hi.peek()) / 2.0;
    }
}

