	heap.Push(&m.lo, -num)
	heap.Push(&m.hi, -heap.Pop(&m.lo).(int)) // lo 的最大值挪到 hi
	if m.hi.Len() > m.lo.Len() {             // 保持 lo 不比 hi 少
